add("LY-001",
"终局：将来有官（正向，单一终局）。两卦合断：初占兑为泽，官鬼巳火居初爻发动——巳火在亥月为月破，官星虽破而动，动不为空、破待填实；巳化寅木妻财为回头生（寅木生巳火），官星有生源不绝；五爻父母未土动化戌土进神，文书印绶一线进益。再占得水地比静卦，官鬼卯木持世，卯木亥月得月建生扶，官星持世而有气——两卦同指：官非虚望，破者待实、世者得位。应期双层：窗口为出亥月后一年内（年档偏月，仕途久远之事取年档而主坐标落月），主坐标为巳月——官鬼巳火填实之月，得官之期（定值）。等级：官星先破后实、得位在中平以上之级，不作极品断（压制依据：初官月破、再占官星仅持世无财印大局）。",
"liuyao\nsystems_used: liuyao（卡面字段名为system、其值照录于首行）\n用神官鬼：初占巳火（月破而动、化回头生）、再占卯木（持世得月生），四源候选枚举后以两卦同指定主。月破按决策序：旺衰先行——巳火休囚而得化神回头生、卯木得月生，破为待实之破（裁决表第4步：破而有根/待出一项成立），不断无官。"+LYT.format(dyn="官鬼巳火化寅木为化回头生、父母未土化戌为化进，两动化俱吉向，定性优先于月破静态表象",rev="源绝三征未齐备；化退化绝无生扶一路不成立（官得回头生与月生）",four="路1本气+（再占官星得月生）／路2元忌仇0（子孙亥水在再占为忌而静、父母动进为助，两相抵偏+）／路3动化+／路4世应计（再占官持世、自占问己）：应子水克世卯木记−只调量级；合参方向成/吉向",obj="求测者将来之官职",use="官鬼巳火（初占）、官鬼卯木（再占世爻）",k="年",chong="冲实巳火之亥支已为月建、冲破不作应期，记无候选",tian="巳月填实月破之官为首选候选",zhong="卯月官星逢值一路为备选",take="填实一路（巳月）",dui="功名门类对表未收仕途得官条目（对表功名条为发案挂榜、以父母为用），明写对表无此门类，按三步原序取填实"),
0.58)
add("LY-002",
"终局：父归（正向，单一终局）。乾为天之泽天夬，上爻父母戌土发动为用神——行人占中用神动而化未土退神，按行人类别条件读法：化退者退离客地、回头向家，主父已在归途；戌土在辰月逢月冲为月破，动而破者待实，且戌得辰月土气、非无根之破。应期双层：窗口为占后一旬内（日档，近行归期按行人门类近应日），主坐标为卯日——戌逢卯合，动而逢合之日父至（定值，行人对表首选机制正合此点）。对象复述：归否与归期断语主语均为出外之父本人，不滑向占者。",
"卡面未标注 tradition 字段，按题面体裁自决\nsystems_used: liuyao\n用神父母戌土上爻独发：月破先过裁决表第4步——戌土辰月同气有根、动而逢合有待出之路，破为待实之破。化退按类别读法（行人）译为归程，不按通用退减读（裁决表定性先行、类别译象在后）。"+LYT.format(dyn="父母戌土化未土为化退，行人类译为已回头在归途；动化方向本身只定退、所指为归",rev="化退无生扶一路不成立（戌土有根、逢合待出）；源绝不涉",four="路1本气+（戌土月同气有根）／路2元忌仇0（原神火爻官鬼午静、忌神木爻妻财寅静，两不动）／路3动化+（类别读法归向）／路4世应不计（代占看用神）；合参方向归/吉向",obj="出外之父之归期",use="父母戌土上爻",k="日",chong="冲实无候选（用神非空非伏）",tian="戌日填实月破一路为备选",zhong="卯日动而逢合为首选、戌日逢值并入逢值路候选池",take="逢值一路中之逢合点（卯日）",dui="行人门类：首选按状态对位——动取逢合之日，正合卯合戌，首选在候选集内有点、按对表取之；闸门为月破待填实，卯在旬内且合破待出不相违，取舍已明"),
0.6)
add("LY-003",
"终局：子病凶危、难愈倾向（负向，单一终局）。地风升静卦，子孙午火伏于世爻妻财丑土之下：午火酉月休囚，飞神丑土为午火所生——伏神生飞、气泄于外而不得养；原神兄弟木全卦不现（六爻皆金水土），生火之源无据；忌神父母亥水两见静压。伏神待出四项：①伏得日月生扶——酉月辰日皆不生火，不成立②飞神空破墓绝——丑土不空不破，不成立③动爻生伏——静卦无动，不成立④冲飞之路——未冲丑一路只在应期层面，未成现盘之通——满足0项且根基两项俱缺，待出不成立。近段药力不见（子孙为医药、伏而不出），远段无原神续救之据，终局按难愈倾向断；死断门槛：用神休囚无气、无生扶两类成立，伏路飞未克绝一类不全，降一格不断必死。应期双层：窗口为占后一旬内（日档），主坐标为午日——伏神逢值反见危重之日（定值）。对象复述：愈否与病势断语主语均为患病之子本人。",
"systems_used: liuyao\n用神子孙午火伏神，飞伏清单有用六无用五逐项：有用得日月生不合、伏旺相不合；无用中休囚无气合、飞生伏泄气另记。原神不上卦按用神章四源枚举记无候选（日月丙辰日、酉月皆非木亲）。"+LYT.format(dyn="静卦无动化，动化方向记无；静态伏泄关系只作量级与待出判据",rev="源绝合判：原神根本不上卦、无从论化退化绝，本条不成立；终局由伏神待出不成立与用神休囚无源直定负向",four="路1本气−（午火休囚无生扶）／路2元忌仇−（原神缺位、忌神水两见）／路3动化0（静卦）／路4世应不计（代占）；合参方向败/凶向",obj="患病之子",use="子孙午火伏神（伏于世爻妻财丑土下）",k="日",chong="未日冲飞神丑土为冲起候选、与终局凶向不自洽（冲飞主出伏向吉），舍",tian="午日伏神填实/逢值一路",zhong="午日逢值与填实同指",take="逢值一路（午日，凶应坐标与终局方向自洽：伏值而泄飞、危见于值日）",dui="疾病门类：首选用神值空/化空取冲空——用神伏而非空，首选无点；次选实破/冲去克神——用神不破、克神为静水无冲去之日可取，次选无点；按三步原序取逢值，查表取舍已明"),
0.55)
add("LY-004",
"终局：父病不治（负向，单一终局）。四度占卜同指一危：第一卦地雷复，父母巳火伏于官鬼寅木之下，飞木生伏本为一线之生；第二卦山泽损，父母巳火现于初爻，卯月火相、辰日土泄；第三四卦风山渐之巽为风，父母午火五爻发动化妻财亥水——化出亥水回头克午火，动化终局为忌克用神且无解（亥水得卯月木泄一层只减克力、不成解法：月木泄水正助火本为通关，然化神亥水临值有气、克势已成）。病势题面已载甚危，四卦用神皆火而渐卦动化回头克为最终收束。近段：病势危重、医药（子孙酉申金）虽在卦而静弱不制水；远段：午火化克应期一到，父病转绝。应期双层：窗口为占后一旬内（日档），主坐标为亥日——化神亥水逢值、回头克应验之日（定值）。对象复述：愈否、病势断语主语逐条均为患病之父本人（本人占、次子占、长子代占、夫人占夫四占所问对象同为父/夫一人，已逐占核对同一）。",
"systems_used: liuyao\n用神父母火四占合参：复卦伏神走飞伏清单（飞生伏有用一项、伏得月相一路，待出中档）只作近段一线生机；终局以渐卦动化回头克定（多占同问以最后一组动卦为动向收束、余卦作旺衰旁证，此取舍已明写）。病占原神木：卯月旺而生火本为有根，然用神动化回头克属路3终局，非原神存续问题，两线分判。"+LYT.format(dyn="父母午火化亥水为化回头克、无通关成解，动化定性凶向；静态四卦火相只调量级不断不治之向",rev="反转两路：源绝三征不齐（原神木旺有根）；动化化退/化绝/化墓一路不成立（本题为回头克非退绝墓）——终局负向出自路3回头克本身，非反转所得",four="路1本气0（火春相而渐卦午火受辰土泄、亥水日后克）／路2元忌仇−（忌神亥水化出临用、原神木生火被化神隔断）／路3动化−（化回头克无解）／路4世应不计（代占/自占混合均看用神父母）；合参以动化忌克与四占同指定凶向",obj="患病之父（四占同一对象）",use="父母巳火（复/损）、父母午火（渐，动）",k="日",chong="冲实无候选（用神不空）",tian="午日用神填实/逢值一路为备选（主见效非凶应，舍）",zhong="亥日化神逢值主凶应",take="逢值一路（亥日，与终局凶向自洽）",dui="疾病门类：首选冲空实空无点；次选用神受冲克而旺相取冲去克神之日——克神亥水无冲去之支在候选内成点（巳冲亥为冲克神而非冲去，巳又为用神本气不取），次选无点；按三步原序取化神逢值，查表取舍已明"),
0.56)
add("LY-005",
"终局：乡试中试（正向，单一终局）。雷风恒之泽风大过，五爻官鬼申金独发：申金临申月月建、旺相发动，化酉金进神，官星旺而化进，功名之星进益有力；父母亥水居四爻静而得申金动生，文书一线有源；子孙午火为忌（克官）静居三爻、申月休囚，克力不足。官父两线俱可用，中试之断成立，名次以官星进神之势在中平以上（等级压制依据无、按官旺化进足级给至中上，不拔至解元之级：父母仅静而得生、无独旺之象）。应期双层：窗口为放榜旬内（日档），主坐标为亥日——父母亥水逢值、发案之日（定值，发案对表父母逢值冲一路：父静者逢值逢冲，取逢值点）。",
"systems_used: liuyao\n用神双主：官鬼申金（功名本体）、父母亥水（文书），两现合参按黄金策求名父鬼双主口径并读、缺一不成——本卦两主俱现且官动生父，成链。"+LYT.format(dyn="官鬼申金化酉金为化进神，动化定性吉向，静态子孙克官只调量级",rev="源绝三征未齐备；化退化绝一路不成立（化进）",four="路1本气+（官临月建旺动）／路2元忌仇+（官动生父、忌神子孙休囚静）／路3动化+（化进）／路4世应不计（自占功名看官父用神）；合参方向成/吉向",obj="求测者之乡试功名",use="官鬼申金五爻（动）、父母亥水四爻",k="日",chong="巳日冲父母亥水一路并入逢值路之逢冲候选（对表父静逢值冲并列，取逢值点、舍逢冲点，理由：官星化进主顺遂、取直值不取冲动）",tian="填实无候选（父不空不破）",zhong="亥日父母逢值",take="逢值一路（亥日）",dui="功名发案门类：以父母为用神五分对位——父旺而静者逢值冲之日，首选机制在候选集内有点（亥值），按对表取逢值点，查表取舍已明"),
0.65)
add("LY-006",
"终局：求婚可成（正向，单一终局）。山火贲之水地比，四爻齐动：世爻妻财未土发动化戌土进神——男占以妻财为用、世即求婚之人，用神持世而化进，按婚姻类别条件读法世/用化进优先作婚事推进可成读；四爻官鬼酉金动化申金退神、初爻父母子水动化未土、上爻子孙巳火动化子水回头克，诸动主议婚过程多阻多变：间爻发动主阻隔、媒妁与两家言语反复，然用神化进之主链不被回头克所及（受克者为子孙巳火、非用神未土）。近段议婚有阻、远段世财化进填实而定。应期双层：窗口为占后一月内（月档），主坐标为未日——世财未土逢值、婚议定成之日（定值）。",
"systems_used: liuyao\n用神妻财未土持世而动：卯月休囚、乙丑日丑冲未为动之由（冲动有气、非日破：未土有戌化进之路与丑土同气之根）。多动对象定位逐爻核：官鬼酉为对方家势、父母子为媒妁文书、子孙巳为闲杂之扰，各归其位不混入用神终局。"+LYT.format(dyn="妻财未土化戌土为化进，婚占类别读法优先成读；子孙巳火化子水回头克只及其自身一爻、不翻用神定性",rev="化退/化绝无生扶一路：官鬼酉化退申只及其爻、非用神化退，不成立；源绝不涉",four="路1本气0（未土休囚而动、化进有路转+）／路2元忌仇0（原神子孙巳动而化回头克自败、忌神兄弟寅静，两相抵）／路3动化+（用神化进）／路4世应计（婚占世应分指双方）：应兄弟寅木克世未土记−只调量级（过程受阻）；合参方向成/吉向",obj="求测者之求婚事",use="妻财未土世爻（动）",k="月",chong="冲实无候选（用神动不为空）",tian="戌日化神填实一路为备选",zhong="未日用神逢值",take="逢值一路（未日）",dui="婚姻门类：首选世/用动而空取实空——用神动而不空，首选无点；次选动而破取实破——用神不破，次选无点；按三步原序取逢值，查表取舍已明"),
0.5)
add("LY-007",
"终局：去迎可遇（正向，单一终局）。水泽节之火泽睽：五爻父母戌土发动为行人用神，戌土丑月同气、丙戌日临值有根，动化未土退神——行人类别读法化退为退离客地、已在归途；世爻兄弟申金四爻发动化酉金进神——迎者一线化进，按行人读法为脚步向前、渐近行人，两路同指途中相遇。上爻子孙子水动化巳火只主途中消息虚惊、不涉相遇主线。应期双层：窗口为占后三日内（日档，近迎之事），主坐标为未日——父母戌土化神未土填实、父归至/相遇之期（定值）。对象复述：行人断语主语为父本人、迎候断语主语为占者本人，两线分开写如上，不相回收。",
"systems_used: liuyao\n用神父母戌土：临日值有根，化退按行人类别读法译归（裁决表先定退向、类别译象在后，与LY-002同法）。世爻申金化进为迎者线、与用神线分判（对象对齐表三行已列）。"+LYT.format(dyn="父母戌土化未土化退（行人译归）、世申金化酉金化进（迎者渐近），两动化同向收敛",rev="化退无生扶一路不成立（戌土临日有根）；源绝不涉",four="路1本气+（戌土临日值）／路2元忌仇0（原神官鬼午静、忌神妻财辰静）／路3动化+（类别读法）／路4世应不计（迎候之事世应已分线入对象对齐、不重复计符）；合参方向遇/吉向",obj="归途之父（行人）与往迎之占者",use="父母戌土五爻（行人）、世爻兄弟申金（迎者）",k="日",chong="冲实无候选（用神不空不伏）",tian="未日化神填实为首选候选",zhong="戌日用神逢值一路为备选",take="填实一路（未日）",dui="行人门类：首选按状态对位——化退取化退而归之期，正合化神填实之未日，首选在候选集内有点、按对表取之，查表取舍已明"),
0.58)
add("LY-008",
"终局：病愈（正向，单一终局）。泽天夬之雷天大壮，五爻子孙酉金持世独发：子孙为福神医药，申月临月建旺相、持世发动主药力临身；酉化申金退神——世/用旺相有根而化退，按化退权重低档另断：退的是病势之退（退神章病占子孙化退主病退之读与旺相根气合参），不作福神消退之凶读。官鬼寅木居应、申月临绝、辛卯日虽临值而月绝压之，病星无力。近段危症之象在药力未及，远段子孙旺动而解。病位：取象之爻官鬼寅木二爻——爻位路二爻主腿与下腹；五行路木主肝胆筋；六神卡面未载（残损注明），两路同指筋骨肝胆一区，病位落此区、程度以危症可解为限。应期双层：窗口为占后一旬内（日档），主坐标为申日——化神申金逢值、病退见愈之日（定值）。对象复述：愈否、病势、病位断语主语均为占病者本人（自占）。",
"卡面未标注 tradition 字段，按题面体裁自决\nsystems_used: liuyao\n用神双线：世爻子孙酉金（自占病以世与福神合看）、官鬼寅木为病星。酉金临月建为第一权重，化退走合流E第1档（旺相有根化退权重低）。病位走病位取象复核三路：爻位/五行两路同指、六神一路卡面未载明写缺路，两路交集成立才落病位。"+LYT.format(dyn="子孙酉金化申金为化退，旺相有根之化退按低权重另断为病势之退，定性维持吉向",rev="化退无生扶一路不成立（世临月建有根）；源绝三征未齐备（原神亥水子水在卦得申金生）",four="路1本气+（世子孙临月建旺动）／路2元忌仇+（原神妻财亥子得金生、忌神官鬼临绝）／路3动化0偏+（化退低权重）／路4世应计（自占世即用神线）：应官鬼寅克世记−，世应已并入路1不重复计、只调量级；合参方向愈/吉向",obj="占病者本人之病",use="子孙酉金世爻（动）、官鬼寅木应爻（病星）",k="日",chong="冲实无候选（用神不空）",tian="填实无候选（化神不空不破、申为化神逢值并入逢值路）",zhong="申日化神逢值、酉日世爻逢值，两点同路取申（化退应于化神值日）",take="逢值一路（申日）",dui="疾病门类：首选冲空实空无点（用神不空）；次选实破/冲去克神——病星寅木临绝无克神可冲，次选无点；按三步原序取逢值（化神值日），查表取舍已明"),
0.6)

with open(f"{BASE}/runs/round78/batches.json",encoding="utf-8") as f:
    batches=json.load(f)
ids=batches["B06"]
assert set(E.keys())==set(ids), (set(ids)-set(E.keys()), set(E.keys())-set(ids))
for cid in ids:
    with open(f"{BASE}/inputs-dev12/{cid}.json",encoding="utf-8") as f:
        card=json.load(f)
    txt,extra,conf,trig=E[cid]
    if cid in ("LY-001","LY-002","LY-008"):
        basis=extra
    else:
        if "tradition" in card:
            first=card["tradition"]
        elif "system" in card:
            first=card["system"]
        else:
            first="卡面未标注 tradition 字段，按题面体裁自决"
        basis=f"{first}\n{extra}"
    obj={"case_id":cid,"prediction_text":txt,"basis":basis,"confidence":conf,"trigger":trig}
    with open(f"{OUT}/{cid}.json","w",encoding="utf-8") as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
print("B06 written", len(ids))
